<script>(()=>{const picker=document.getElementById('recovery-photo-picker'),input=document.getElementById('recovery-photos'),preview=document.getElementById('recovery-photo-preview'),count=document.getElementById('recovery-photo-count'),status=document.getElementById('recovery-ai-status'),panel=document.getElementById('recovery-camera-panel'),video=document.getElementById('recovery-camera-video');let files=[],selected=null,stream=null;
function sync(){const dt=new DataTransfer();files.forEach(f=>dt.items.add(f));input.files=dt.files;count.textContent=`${files.length} de 5 fotografías`}
function render(){preview.innerHTML='';files.forEach((file,i)=>{const card=document.createElement('div');card.className='photo-card';const img=document.createElement('img');img.src=URL.createObjectURL(file);img.alt=file.name;const label=document.createElement('label'),radio=document.createElement('input');radio.type='radio';radio.name='recovery_label_photo';radio.checked=selected===i;radio.onchange=()=>selected=i;label.append(radio,document.createTextNode('Etiqueta de la unidad'));const remove=document.createElement('button');remove.type='button';remove.className='btn danger';remove.textContent='Eliminar imagen';remove.onclick=()=>{files.splice(i,1);if(selected===i)selected=null;else if(selected>i)selected--;sync();render()};card.append(img,label,remove);preview.append(card)})}
function add(list){const available=5-files.length;files.push(...[...list].slice(0,available));if(list.length>available)alert('Solo se permiten 5 fotografías por caso.');picker.value='';sync();render()}
picker.addEventListener('change',()=>add(picker.files));document.getElementById('recovery-start-camera').onclick=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment',width:{ideal:1600}},audio:false});video.srcObject=stream;panel.hidden=false}catch(e){status.textContent='No fue posible abrir la webcam. Revisa los permisos del navegador.'}};
function stop(){stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;panel.hidden=true}document.getElementById('recovery-stop-camera').onclick=stop;document.getElementById('recovery-capture').onclick=()=>{if(!stream)return;if(files.length>=5){alert('Ya alcanzaste el máximo de 5 fotografías.');return}const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(blob=>{if(blob)add([new File([blob],`unidad-${Date.now()}.jpg`,{type:'image/jpeg'})])},'image/jpeg',.9)};
document.getElementById('recovery-analyze-label').onclick=async function(){if(selected===null||!files[selected]){status.textContent='Marca primero la fotografía de la etiqueta.';return}this.disabled=true;status.textContent='Analizando etiqueta...';const body=new FormData();body.append('company_id',document.getElementById('company_id').value);body.append('image',files[selected]);try{const response=await fetch('{{ route('ai.analyze-storage-label') }}',{method:'POST',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body});const result=await response.json();if(!response.ok||!result.success)throw new Error(result.message||'No fue posible analizar la etiqueta.');const map={brand:'storage_brand',model:'storage_model',capacity:'storage_capacity',serial_number:'storage_serial',interface:'storage_interface'};Object.entries(map).forEach(([key,id])=>{if(result.data[key])document.getElementById(id).value=result.data[key]});status.textContent=`Datos cargados. Confianza: ${Math.round((result.data.confidence||0)*100)}%. Revisa antes de guardar.`}catch(e){status.textContent=e.message}finally{this.disabled=false}};window.addEventListener('beforeunload',stop)})()</script>
@endif
<script>(()=>{const rut=document.getElementById('rut'), company=document.getElementById('company_id'), status=document.getElementById('client-status');let timer;rut?.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(async()=>{if(rut.value.length<7)return;const u=new URL('{{ route('clients.lookup-by-rut') }}',location.origin);u.searchParams.set('company_id',company.value);u.searchParams.set('rut',rut.value);const r=await fetch(u,{headers:{Accept:'application/json'}});if(!r.ok)return;const d=await r.json();status.textContent=d.found?'Cliente existente encontrado':'Cliente nuevo';if(d.found){['name','email','phone','address'].forEach(k=>document.getElementById('client_'+k).value=d.client[k]??'')}} ,350)});const net=document.getElementById('net_amount');const money=n=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(n||0);function totals(){if(!net)return;const n=Number(net.value||0);document.getElementById('net-label').textContent=money(n);document.getElementById('tax-label').textContent=money(Math.round(n*.19));document.getElementById('total-label').textContent=money(Math.round(n*1.19))}net?.addEventListener('input',totals);totals()})()</script>
